package com.bank.flag.service;

import java.util.logging.Logger;

// Computes the bitwise complement within the number's own bit width.
public class FlagComplementService {
    private static final Logger log = Logger.getLogger(FlagComplementService.class.getName());

    public int complement(int flag) {
        if (flag == 0) return 1; // convention: complement of 0 is 1
        int bitCount = 0, n = flag;
        while (n > 0) { bitCount++; n >>= 1; }     // measure the width
        int mask = (1 << bitCount) - 1;            // all-ones mask of that width
        int result = flag ^ mask;                  // flip only the used bits
        log.info(() -> "Complement of " + flag + " (width " + bitCount + ") = " + result);
        return result;
    }
}
